fn first_even(numbers: &[i32]) -> Option<i32> {
    for &n in numbers {   // each item is a &i32; &n gives the plain number n
        if n % 2 == 0 {
            return Some(n);
        }
    }
    None
}

fn main() {
    let result = first_even(&[3, 7, 8, 10]);
    println!("{:?}", result);
}

